const root=new URL('./audio-assets/',import.meta.url);
const scores=['base','regular','super','super-super'];
const prefsKey='goonageddon-audio-v2-settings';
const phaseKey='goonageddon-audio-v2-position';
const heardKey='goonageddon-audio-v2-presented-audio';
const cueProfiles={
  'spin-start':{priority:0,limit:1},'reel-stop':{priority:0,limit:6},destruction:{priority:1,limit:2},
  'wild-land':{priority:2,limit:4,duck:.75},'scatter-land':{priority:3,limit:6,duck:.75},
  'count-up':{priority:1,limit:1},'bonus-complete':{priority:4,limit:1,duck:.72},
  'regular-trigger':{priority:5,limit:1,duck:.56},'super-trigger':{priority:5,limit:1,duck:.56},
  'super-super-trigger':{priority:5,limit:1,duck:.56},'big-win':{priority:5,limit:1,duck:.57},
  'mega-win':{priority:5,limit:1,duck:.57},'max-win':{priority:6,limit:1,duck:.52}
};
const cueMedia = {
  "big-win": "",
  "bonus-complete": "",
  "count-up": "",
  "destruction": "",
  "max-win": "",
  "mega-win": "",
  "reel-stop": "",
  "regular-trigger": "",
  "scatter-land": "",
  "spin-start": "",
  "super-super-trigger": "",
  "super-trigger": "",
  "wild-land": ""
};
const assets={base:3767040,regular:3954240,super:4816320,'super-super':4411200};
const noop=()=>{};

export function readAudioSettings(){
  let saved={};
  try{saved=JSON.parse(localStorage.getItem(prefsKey))??{};}catch{}
  const volume=(key,fallback)=>Number.isFinite(saved[key])?Math.max(0,Math.min(1,saved[key])):fallback;
  return {music:volume('music',.72),effects:volume('effects',.86),mute:saved.mute===true};
}

export function saveAudioSettings({music,effects,mute}){
  try{localStorage.setItem(prefsKey,JSON.stringify({music,effects,mute}));}catch{}
}

export function scoreAtCursor(events,cursor){
  const latest=events.findLast(e=>e.index<=cursor&&['bonus','summary','end'].includes(e.type));
  return latest?.type==='bonus'?latest.tier:-1;
}

export function createAudio(settings){
  let ctx,music,effects,duck,master,current,retiring;
  let requested='base',generation=0,sceneGeneration=0,silenced=false,duckUntil=0,duckLevel=1;
  let scoreLoads,roundId,eventIndex,ordinals,heard;
  const decoded=new Map(),positions=new Map(),voices=new Set();
  try{
    const saved=JSON.parse(sessionStorage.getItem(phaseKey));
    if(saved?.time>Date.now()-30*60*1000){
      for(const name of scores)if(Number.isFinite(saved[name])&&saved[name]>=0)positions.set(name,saved[name]);
    }
  }catch{}

  const running=()=>ctx?.state==='running'&&!document.hidden;
  const audible=()=>running()&&!silenced&&!settings().mute&&settings().effects>0;
  function load(name,isScore=false){
    if(decoded.has(name))return decoded.get(name);
    const pending=(async()=>{
      if(!isScore){
        const bytes=Uint8Array.from(atob(cueMedia[name]),character=>character.charCodeAt(0));
        return ctx.decodeAudioData(bytes.buffer);
      }
      const path='music/'+name;
      async function fetchAudio(ext){
        const response=await fetch(new URL(path+ext,root));
        if(!response.ok)throw Error('Audio asset unavailable');
        const buffer=await ctx.decodeAudioData(await response.arrayBuffer());
        const expected=assets[name]*buffer.sampleRate/48000;
        const frames=Math.round(expected);
        if(isScore&&buffer.length!==frames){
          // Some AAC decoders preserve the last packet's tail padding despite the container edit list.
          if(ext!=='.m4a'||buffer.length<frames||buffer.length-frames>1024*buffer.sampleRate/48000)throw Error('Unexpected loop length');
          const trimmed=ctx.createBuffer(buffer.numberOfChannels,frames,buffer.sampleRate);
          for(let c=0;c<buffer.numberOfChannels;c++)trimmed.copyToChannel(buffer.getChannelData(c).subarray(0,frames),c);
          return trimmed;
        }
        return buffer;
      }
      return fetchAudio('.opus').catch(()=>fetchAudio('.m4a'));
    })().catch(error=>{
      if(decoded.get(name)===pending)decoded.delete(name);
      throw error;
    });
    decoded.set(name,pending);
    return pending;
  }
  function prime(tier){
    const name=scores[tier+1];
    if(ctx&&name)void load(name,true).then(()=>trimScores(name)).catch(noop);
  }
  function trimScores(prefetched){
    for(const name of scores.slice(1)){
      if(name!==prefetched&&name!==requested&&name!==current?.name&&name!==retiring?.name)decoded.delete(name);
    }
  }
  function offset(voice,time){
    return (voice.at+Math.max(0,time-voice.start))%voice.source.buffer.duration;
  }
  function fadeValue(voice,time){
    if(!voice.fade)return 1;
    const {from,to,at,seconds}=voice.fade;
    const t=Math.max(0,Math.min(1,(time-at)/seconds));
    return Math.sqrt(from*from*(1-t)+to*to*t);
  }
  function fadeScore(voice,time,to,seconds,from=fadeValue(voice,time)){
    const points=Float32Array.from({length:64},(_,i)=>Math.sqrt((from*from*(63-i)+to*to*i)/63));
    const param=voice.gain.gain;
    param.cancelScheduledValues(0);
    param.setValueCurveAtTime(points,time,seconds);
    voice.fade={at:time,seconds,from,to};
  }
  function selectScore(){
    if(!running()||silenced||current?.name===requested||scoreLoads===generation)return;
    const name=requested, request=generation;
    scoreLoads=request;
    void load(name,true).then(buffer=>{
      if(request!==generation||!running()||silenced||current?.name===name)return;
      const now=ctx.currentTime, duration=name==='base'?1.05:.75;
      if(retiring){
        fadeScore(retiring,now,0,.025);
        retiring.source.stop(now+.026);
      }
      if(current){
        const previous=current;
        fadeScore(previous,now,0,duration);
        positions.set(previous.name,offset(previous,now+duration));
        previous.source.stop(now+duration);
        retiring=previous;
      }
      const source=ctx.createBufferSource(), gain=ctx.createGain();
      const at=(positions.get(name)??0)%buffer.duration;
      source.buffer=buffer;
      source.loop=true;
      source.loopEnd=buffer.duration;
      source.connect(gain).connect(music);
      const voice={name,source,gain,at,start:now};
      current=voice;
      source.onended=()=>{
        source.disconnect();gain.disconnect();
        if(retiring===voice)retiring=null;
        trimScores();
      };
      fadeScore(voice,now,1,retiring?duration:.18,0);
      source.start(now,at);
      trimScores();
    }).catch(noop).finally(()=>{if(scoreLoads===request)scoreLoads=undefined;});
  }
  function setScore(tier){
    const name=scores[tier+1]??'base';
    if(requested!==name){
      requested=name;
      // Each new feature starts from its loop origin. Resume restores a saved phase separately.
      generation++;
    }
    selectScore();
  }
  function enterBonus(tier){
    const name=scores[tier+1];
    if(name&&requested!==name)positions.delete(name);
    setScore(tier);
  }
  function refresh(){
    if(!ctx)return;
    const prefs=settings(), time=ctx.currentTime;
    music.gain.setTargetAtTime(prefs.mute||silenced?0:prefs.music,time,.028);
    effects.gain.setTargetAtTime(prefs.mute||silenced?0:prefs.effects,time,.018);
    if(prefs.mute||prefs.effects===0)clearEffects();
    selectScore();
  }
  function unlock(){
    try{
      const initial=!ctx;
      if(!ctx){
        ctx=new AudioContext();
        music=ctx.createGain();effects=ctx.createGain();duck=ctx.createGain();
        music.gain.value=effects.gain.value=0;
        master=ctx.createWaveShaper();
        // Soft safety ceiling, linear through normal program levels. Oversampling guards transients.
        master.curve=Float32Array.from({length:4097},(_,i)=>{
          const x=i/2048-1, magnitude=Math.abs(x);
          return magnitude<=.65?x:Math.sign(x)*(.65+.14*Math.tanh((magnitude-.65)/.14));
        });
        master.oversample='4x';
        music.connect(duck).connect(master);
        effects.connect(master);
        master.connect(ctx.destination);
        for(const name of Object.keys(cueProfiles))void load(name).catch(noop);
        prime(-1);
      }
      if(!document.hidden&&ctx.state!=='running')void ctx.resume().then(refresh).catch(noop);
      else if(running()&&initial)refresh();
      else if(running())selectScore();
    }catch{}
  }
  function hold(param,time){
    if(param.cancelAndHoldAtTime)param.cancelAndHoldAtTime(time);
    else{const value=param.value;param.cancelScheduledValues(time);param.setValueAtTime(value,time);}
  }
  function releaseDuck(){
    if(!duck)return;
    const time=ctx.currentTime;
    duckUntil=time;
    duckLevel=1;
    hold(duck.gain,time);
    duck.gain.linearRampToValueAtTime(1,time+.16);
  }
  function dip(level,seconds){
    if(!level)return;
    const time=ctx.currentTime;
    duckLevel=time<duckUntil?Math.min(duckLevel,level):level;
    duckUntil=Math.max(duckUntil,time+Math.min(1.35,seconds)+.035);
    hold(duck.gain,time);
    duck.gain.linearRampToValueAtTime(duckLevel,time+.027);
    duck.gain.setValueAtTime(duckLevel,duckUntil);
    duck.gain.linearRampToValueAtTime(1,duckUntil+.39);
  }
  function release(voice,seconds=.045){
    if(voice.released)return;
    voice.released=true;
    const time=ctx.currentTime;
    hold(voice.gain.gain,time);
    voice.gain.gain.linearRampToValueAtTime(0,time+seconds);
    voice.source.stop(time+seconds+.001);
  }
  function clearEffects(){
    sceneGeneration++;
    for(const voice of voices)release(voice);
    releaseDuck();
  }
  function setSilenced(value){
    const next=!!value;
    if(next!==silenced){
      silenced=next;
      if(next){generation++;clearEffects();}
    }
    refresh();
  }

  // Presentation-only journal. It never participates in wallet state or recorded gameplay checkpoints.
  function beginRound(id){
    roundId=id==null?null:String(id);
    eventIndex=null;
    let entry;
    if(roundId!==null)try{entry=JSON.parse(localStorage.getItem(heardKey));}catch{}
    heard=new Set(entry?.roundId===roundId&&Array.isArray(entry.cues)?entry.cues:[]);
  }
  function beginEvent(index){eventIndex=index;ordinals=new Map();}
  function cueIdentity(name){
    if(roundId==null||eventIndex==null)return null;
    const take=ordinals.get(name)??0;
    ordinals.set(name,take+1);
    return `${eventIndex}/${name}/${take}`;
  }
  function remember(id,key){
    if(roundId!==id||key===null)return;
    heard.add(key);
    try{localStorage.setItem(heardKey,JSON.stringify({roundId,cues:[...heard]}));}catch{}
  }

  function cue(name,{length=Infinity,delay=0,level=1}={}){
    const profile=cueProfiles[name];
    const key=cueIdentity(name),id=roundId;
    if(key!==null&&heard.has(key))return noop;
    if(!profile||!ctx||silenced||settings().mute||settings().effects===0||document.hidden)return noop;
    const called=performance.now(), scene=sceneGeneration;
    let cancelled=false,voice;
    void load(name).then(buffer=>{
      if(cancelled||scene!==sceneGeneration||!audible()||performance.now()-called>225)return;
      const active=[...voices].filter(item=>!item.released&&item.end>ctx.currentTime);
      const same=active.filter(item=>item.name===name);
      if(same.length>=profile.limit){
        if(profile.priority===0)return;
        release(same[0],.018);
      }else if(active.length>=12){
        const victim=active.reduce((lowest,item)=>item.priority<lowest.priority?item:lowest);
        if(victim.priority>profile.priority)return;
        release(victim,.018);
      }
      const start=ctx.currentTime+delay, duration=Math.min(buffer.duration,length);
      const source=ctx.createBufferSource(), gain=ctx.createGain();
      source.buffer=buffer;
      source.connect(gain).connect(effects);
      gain.gain.setValueAtTime(level,start);
      if(duration<buffer.duration){
        gain.gain.setValueAtTime(level,start+Math.max(0,duration-.036));
        gain.gain.linearRampToValueAtTime(0,start+duration);
      }
      voice={name,source,gain,priority:profile.priority,end:start+duration,released:false};
      voices.add(voice);
      source.onended=()=>{voices.delete(voice);source.disconnect();gain.disconnect();};
      dip(profile.duck,duration);
      source.start(start,0,duration);
      if(key!==null){
        if(delay===0)remember(id,key);
        else setTimeout(()=>{if(!voice.released&&running())remember(id,key);},delay*1000);
      }
    }).catch(noop);
    return ()=>{cancelled=true;if(voice)release(voice);};
  }
  function scatter(count,delay=0){
    for(let i=0;i<count;i++)cue('scatter-land',{delay:delay+i*.033,level:1/Math.sqrt(count),length:1.18});
  }
  document.addEventListener('visibilitychange',()=>{
    if(!ctx)return;
    if(document.hidden){clearEffects();void ctx.suspend().catch(noop);}
    else void ctx.resume().then(refresh).catch(noop);
  });
  addEventListener('pagehide',()=>{
    if(!ctx)return;
    if(current)positions.set(current.name,offset(current,ctx.currentTime));
    try{sessionStorage.setItem(phaseKey,JSON.stringify({time:Date.now(),...Object.fromEntries(positions)}));}catch{}
    clearEffects();
    void ctx.suspend().catch(noop);
  });
  addEventListener('pageshow',event=>{
    if(event.persisted&&ctx&&!document.hidden)void ctx.resume().then(refresh).catch(noop);
  });
  return {unlock,refresh,cue,scatter,setSilenced,setScore,prime,enterBonus,clearEffects,releaseDuck,beginRound,beginEvent};
}
